    @staticmethod
    def envelope_sender_is_blank(account: EmailAccount) -> bool:
        """Check backwards-compatible empty envelope configuration after persistence."""
        return account.smtp_envelope_sender == ""

    @staticmethod
    def envelope_sender_is_primary(account: EmailAccount) -> bool:
        """Check that the explicit primary envelope persists without changing the alias."""
        return account.smtp_envelope_sender == "primary@example.com" and account.email_address == "alias@example.com"

    @staticmethod
    def validate_incomplete_imap_account():
        account = EmailAccount(
            provider=EmailProvider.IMAP.value.key,
            name="Incomplete inbox",
            email_address="incomplete@example.com",
        )
        account.full_clean()
        return account

    @staticmethod
    def sent_copy_is_disabled(account: EmailAccount) -> bool:
        """Check that existing and new accounts do not save extra Sent copies by default."""
        return account.save_sent_emails is False

    @staticmethod
    def sent_copy_is_enabled(account: EmailAccount) -> bool:
        """Check that opting into Sent-copy saving persists on the account."""
        return account.save_sent_emails is True

    @staticmethod
    def default_mailboxes_are_mapped(account: EmailAccount) -> bool:
        """Check persisted migration-compatible input receives labels and role defaults."""
        return account.mailboxes["INBOX"]["main_folder"] and account.mailboxes["Sent"]["sent_folder"] and account.mailboxes["Archive"]["label"] == "Archive"

    @staticmethod
    def custom_mailbox_is_saved(account: EmailAccount) -> bool:
        """Check user labels and colors survive model persistence."""
        return account.mailboxes["INBOX"]["label"] == "Customer mail" and account.mailboxes["INBOX"]["color"] == "#2563eb"

    def run_repeated_successful_syncs(self, account: EmailAccount) -> None:
        """Exercise the same partial save as successful polling, twice in succession."""
        self.deleted_account_id = str(account.pk)
        for _ in range(2):
            account.last_sync_finished_at = timezone.now()
            account.next_sync_at = timezone.now()
            account.sync_locked_until = None
            account.last_sync_error = ""
            account.save(update_fields=[
                "last_sync_finished_at", "last_sync_error", "next_sync_at",
                "sync_locked_until", "datetime_updated",
            ])

    @staticmethod
    def has_only_create_log(account: EmailAccount) -> bool:
        """Bookkeeping-only saves preserve the original creation event."""
        logs = ActivityLogManager(account).get_for_object()
        return list(logs.values_list("action", flat=True)) == [ActivityLogAction.CREATE]

    def has_create_and_delete_logs(self, account: EmailAccount) -> bool:
        """The ignored-field gate never suppresses deletion."""
        logs = ActivityLog.objects.filter(
            content_type=ActivityLogManager(account).get_content_type(),
            object_id=self.deleted_account_id,
        )
        return set(logs.values_list("action", flat=True)) == {ActivityLogAction.CREATE, ActivityLogAction.DELETE}

    @staticmethod
    def has_configuration_change_log(account: EmailAccount) -> bool:
        """A useful field keeps the whole diff rather than removing ignored details."""
        log = ActivityLogManager(account).get_for_object().get(action=ActivityLogAction.CHANGE)
        return {change["field"] for change in log.payload} >= {"name", "next_sync_at"}

    @staticmethod
    def has_sync_error_change_log(account: EmailAccount) -> bool:
        """Both error introduction and recovery survive the sync-only gate."""
        log = ActivityLogManager(account).get_for_object().get(action=ActivityLogAction.CHANGE)
        return "last_sync_error" in {change["field"] for change in log.payload}

    def make_failed_sync_account(self, suffix: str) -> tuple[EmailAccount, QuerySet[InboxFolder]]:
        """Create a connected inbox with an existing sync error and real audit signals."""
        user = get_user_model().objects.create_user(username=f"sync-audit-{suffix}")
        inbox = Inbox.objects.create(user=user, name="Sync audit inbox")
        account = EmailAccount.objects.create(
            email_address=f"sync-{suffix}@example.com", status="active",
            sync_enabled=True, mailboxes=["INBOX"], last_sync_error="Previous failure",
        )
        folder = InboxFolder.objects.create(
            inbox=inbox, type="email", related_object_id=str(account.pk),
        )
        return account, InboxFolder.objects.filter(pk=folder.pk)

    def test_sync_handler_records_recovery_once_then_keeps_healthy_sync_quiet(self) -> None:
        """The real lock/refresh/completion path must preserve one old-error-to-empty diff."""
        account, folders = self.make_failed_sync_account("recovery")
        with patch("bloomerp.communication.builtins.emails.sync._resolve_email_adapter_for_account") as resolve:
            resolve.return_value.sync_emails.return_value = []
            result = handle_email_account_sync(folders, email_account_id=str(account.pk))
            self.assertEqual(result.outcome, "completed")
            account.refresh_from_db()
            self.assertEqual(account.last_sync_error, "")
            self.assertIsNone(account.sync_locked_until)
            self.assertIsNotNone(account.last_sync_finished_at)
            changes = ActivityLogManager(account).get_for_object().filter(action=ActivityLogAction.CHANGE)
            self.assertEqual(changes.count(), 1)
            self.assertIn(
                {"field": "last_sync_error", "from": "Previous failure", "to": ""},
                changes.get().payload,
            )
            handle_email_account_sync(folders, email_account_id=str(account.pk))
            self.assertEqual(changes.count(), 1)
            self.assertEqual(resolve.return_value.close.call_count, 2)

    def test_sync_handler_preserves_error_across_identical_failed_retries(self) -> None:
        """Failed retries cannot manufacture recovery or re-log an unchanged error."""
        account, folders = self.make_failed_sync_account("retry")
        with patch("bloomerp.communication.builtins.emails.sync._resolve_email_adapter_for_account") as resolve:
            resolve.return_value.sync_emails.side_effect = RuntimeError("Previous failure")
            for _ in range(2):
                with self.assertRaisesRegex(RuntimeError, "Previous failure"):
                    handle_email_account_sync(folders, email_account_id=str(account.pk))
                account.refresh_from_db()
                self.assertEqual(account.last_sync_error, "Previous failure")
                self.assertIsNone(account.sync_locked_until)
            self.assertEqual(resolve.return_value.close.call_count, 2)
        self.assertFalse(ActivityLogManager(account).get_for_object().filter(action=ActivityLogAction.CHANGE).exists())

    def test_sync_handler_records_changed_failure_without_erasing_previous_error(self) -> None:
        """A different failure records the real old/new errors, never an artificial empty value."""
        account, folders = self.make_failed_sync_account("new-error")
        with patch("bloomerp.communication.builtins.emails.sync._resolve_email_adapter_for_account") as resolve:
            resolve.return_value.sync_emails.side_effect = RuntimeError("Different failure")
            with self.assertRaisesRegex(RuntimeError, "Different failure"):
                handle_email_account_sync(folders, email_account_id=str(account.pk))
        account.refresh_from_db()
        self.assertEqual(account.last_sync_error, "Different failure")
        log = ActivityLogManager(account).get_for_object().get(action=ActivityLogAction.CHANGE)
        self.assertIn(
            {"field": "last_sync_error", "from": "Previous failure", "to": "Different failure"},
            log.payload,
        )

    def test_skipped_syncs_preserve_errors_without_false_recovery_logs(self) -> None:
        """Locked, unlinked and non-polling accounts must not claim successful recovery."""
        for reason in ("account_locked", "no_linked_folders", "not_polling"):
            with self.subTest(reason=reason):
                account, folders = self.make_failed_sync_account(reason)
                if reason == "account_locked":
                    account.sync_locked_until = timezone.now() + timedelta(minutes=5)
                    account.save(update_fields=["sync_locked_until"])
                elif reason == "not_polling":
                    account.sync_mode = "push"
                    account.save(update_fields=["sync_mode"])
                else:
                    folders = folders.none()
                initial_changes = ActivityLogManager(account).get_for_object().filter(action=ActivityLogAction.CHANGE).count()
                with patch("bloomerp.communication.builtins.emails.sync._resolve_email_adapter_for_account") as resolve:
                    result = handle_email_account_sync(folders, email_account_id=str(account.pk))
                    resolve.assert_not_called()
                self.assertEqual(result.reason, reason)
                self.assertEqual(result.outcome, "skipped")
                account.refresh_from_db()
                self.assertEqual(account.last_sync_error, "Previous failure")
                self.assertIsNone(account.last_sync_finished_at)
                self.assertEqual(
                    ActivityLogManager(account).get_for_object().filter(action=ActivityLogAction.CHANGE).count(),
                    initial_changes,
                )
                if reason != "account_locked":
                    self.assertIsNone(account.sync_locked_until)
                    self.assertIsNotNone(account.next_sync_at)
